CREATE TRIGGER `payment_allocations_bounds` BEFORE INSERT ON `payment_allocations` WHEN NOT EXISTS (SELECT 1 FROM payments p JOIN documents d ON d.id = NEW.document_id WHERE p.id = NEW.payment_id AND p.status = 'confirmed' AND d.client_id = p.client_id AND d.currency = p.currency AND d.frozen_at IS NOT NULL AND d.status <> 'void' AND d.type IN ('tax_invoice', 'export_invoice', 'debit_note')
      AND (p.kind = 'payment' OR (p.kind = 'tds' AND NEW.kind = 'allocate' AND d.type IN ('tax_invoice', 'debit_note') AND d.currency = 'INR'))
      AND CASE NEW.kind
        WHEN 'allocate' THEN NEW.amount_minor <= d.total_minor - d.credited_minor - (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') - (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') AND (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = p.id) + NEW.amount_minor <= p.amount_minor
        ELSE NEW.amount_minor <= (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') + d.credited_minor + (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') - d.total_minor AND NEW.amount_minor <= (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = p.id AND pna.document_id = d.id) END) BEGIN SELECT RAISE(ABORT, 'payment_allocations_bounds: a confirmed payment goes onto an issued, live invoice or debit note of its client and currency, never above the balance or the payment; a release takes back no more than the excess it holds'); END;
