CREATE TRIGGER `ledger_result_check` INSTEAD OF INSERT ON `ledger_result` WHEN EXISTS (SELECT 1 FROM json_each(NEW.payment_ids) pj JOIN payments p ON p.id = pj.value WHERE p.status = 'confirmed' AND ((SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = p.id) > p.amount_minor OR (p.kind = 'tds' AND NOT ((SELECT count(*) FROM payment_allocations t WHERE t.payment_id = p.id) = 1 AND (SELECT sum(t.amount_minor) FROM payment_allocations t WHERE t.payment_id = p.id AND t.kind = 'allocate') = p.amount_minor)))) OR EXISTS (SELECT 1 FROM json_each(NEW.document_ids) j JOIN documents d ON d.id = j.value WHERE d.type IN ('tax_invoice', 'export_invoice', 'debit_note') AND d.frozen_at IS NOT NULL AND (d.paid_minor IS NOT (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') OR d.tds_minor IS NOT (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') OR d.balance_minor IS NOT max(0, d.total_minor - (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') - d.credited_minor - (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate')) OR (d.status IN ('issued', 'partially_paid', 'paid', 'partially_credited', 'credited') AND d.status IS NOT CASE WH